<?php require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/otp.php'; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $email=trim($_POST['email']); $s=db()->prepare('SELECT COUNT(*) FROM password_reset_limits WHERE email=? AND requested_at >= DATE_SUB(NOW(), INTERVAL 5 HOUR)'); $s->execute([$email]); if($s->fetchColumn()>=3){$msg='Reset limit exceeded. Try again after the 5 hour cooldown.';} else {db()->prepare('INSERT INTO password_reset_limits(email,requested_at) VALUES (?,NOW())')->execute([$email]); $u=find_user_by_email($email); if($u) create_otp((int)$u['id'],$email,'password_reset'); $_SESSION['reset_email']=$email; redirect('/auth/reset-password.php');}} auth_header('Forgot Password'); ?><h2 class="brand">Reset your password</h2><?php if($msg):?><div class="alert alert-warning"><?=e($msg)?></div><?php endif;?><form method="post" class="vstack gap-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="email" name="email" class="form-control" placeholder="Email" required><button class="btn btn-premium">Send OTP</button></form><?php auth_footer(); ?>
